from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_HALF_DOWN, ROUND_UP, ROUND_DOWN, ROUND_CEILING, ROUND_FLOOR

def convert_currency_amount(amount: str, exchange_rate: str, rounding_mode: str = "ROUND_HALF_UP") -> dict:
    try:
        if not isinstance(amount, (str, int, float)) or not isinstance(exchange_rate, (str, int, float)):
            return {"status": "ERROR", "error": "Invalid input types."}

        mode_map = {
            "ROUND_HALF_UP": ROUND_HALF_UP,
            "ROUND_HALF_EVEN": ROUND_HALF_EVEN,
            "ROUND_HALF_DOWN": ROUND_HALF_DOWN,
            "ROUND_UP": ROUND_UP,
            "ROUND_DOWN": ROUND_DOWN,
            "ROUND_CEILING": ROUND_CEILING,
            "ROUND_FLOOR": ROUND_FLOOR,
        }

        mode = mode_map.get(str(rounding_mode).upper())
        if mode is None:
            return {"status": "ERROR", "error": f"Unsupported rounding mode: {rounding_mode}"}

        dec_amount = Decimal(str(amount).strip())
        dec_rate = Decimal(str(exchange_rate).strip())

        if dec_amount < Decimal("0"):
            return {"status": "ERROR", "error": "Amount cannot be negative."}
        if dec_rate <= Decimal("0"):
            return {"status": "ERROR", "error": "Exchange rate must be positive."}

        converted = dec_amount * dec_rate
        result = converted.quantize(Decimal("0.01"), rounding=mode)

        return {
            "status": "SUCCESS",
            "amount": str(dec_amount),
            "exchange_rate": str(dec_rate),
            "converted_amount": str(result),
            "converted_value": float(result)
        }
    except (InvalidOperation, ValueError, TypeError) as e:
        return {"status": "ERROR", "error": f"Invalid numerical value: {str(e)}"}
    except Exception as e:
        return {"status": "ERROR", "error": str(e)}
